cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log(t.name + ':', cols.map(c => c.name).join(', '));
  const sample = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 2').all();
  console.log('  Sample:', JSON.stringify(sample).slice(0, 500));
}
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
const row = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'A58410'\").get();
if (row) {
  console.log(JSON.stringify(row, null, 2));
} else {
  // Try case-insensitive or partial match
  const rows = db.prepare(\"SELECT booking_id FROM flight_bookings WHERE booking_id LIKE '%58410%'\").all();
  console.log('No exact match. Similar:', rows);
  // Also try all booking IDs
  const allIds = db.prepare('SELECT booking_id FROM flight_bookings').all();
  console.log('All booking IDs:', allIds.map(r => r.booking_id));
}
"

